package village.naruto.health;
import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.plugin.java.JavaPlugin;
/** Original bounded nameplates; persistent backups preserve preexisting names. */
public final class HeadBars {
 private static final String ORIG="hbvnh1.original.",LAST="hbvnh1.last.";
 private static final Map<UUID,State> states=new HashMap<UUID,State>();
 private static final class State {LivingEntity e;String name,label,originalTag,lastTag,lastName;boolean visible;}
 private static String hash(String s)throws Exception {byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder o=new StringBuilder();for(byte x:b)o.append(String.format("%02x",x&255));return o.toString();}
 private static boolean enemy(LivingEntity e){if(e instanceof Player||e instanceof ArmorStand)return false;if(e instanceof Monster)return true;if(e instanceof Creature&&((Creature)e).getTarget() instanceof Player)return true;try{String n=e.getClass().getMethod("getHandle").invoke(e).getClass().getName();return Arrays.asList("net.narutomod.entity.EntityGaara$EntityCustom","net.narutomod.entity.EntityKisameHoshigaki$EntityCustom","net.mcreator.ahznbcursemarkaddon.entity.EntityEdotenseiHashirama$EntityCustom","net.mcreator.kabutoaddon.entity.EntityAy$EntityCustom","net.mcreator.ahznbcursemarkaddon.entity.EntityEdotenseiMadara$EntityCustom").contains(n);}catch(Exception ex){return false;}}
 private static State read(LivingEntity e)throws Exception {String original=null,last=null;for(String tag:e.getScoreboardTags()){if(tag.startsWith(ORIG)){if(original!=null)return null;original=tag;}if(tag.startsWith(LAST)){if(last!=null)return null;last=tag;}}if(original==null||last==null||original.length()>8192||last.length()!=LAST.length()+64)return null;DataInputStream in=new DataInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(original.substring(ORIG.length()))));State s=new State();s.e=e;s.visible=in.readBoolean();s.name=in.readBoolean()?in.readUTF():null;s.label=in.readUTF();if(in.available()!=0)return null;s.originalTag=original;s.lastTag=last;String now=e.getCustomName();if(now!=null&&last.equals(LAST+hash(now)))s.lastName=now;return s;}
 private static void tags(State s){s.e.removeScoreboardTag(s.originalTag);if(s.lastTag!=null)s.e.removeScoreboardTag(s.lastTag);}
 private static void restore(State s){try{if(s.lastName!=null&&s.lastName.equals(s.e.getCustomName())){s.e.setCustomName(s.name);s.e.setCustomNameVisible(s.visible);}tags(s);}catch(Exception ignored){}}
 private static State fresh(LivingEntity e)throws Exception {for(String t:e.getScoreboardTags())if(t.startsWith(ORIG)||t.startsWith(LAST))return null;State s=new State();s.e=e;s.name=e.getCustomName();s.visible=e.isCustomNameVisible();s.label=s.name==null?e.getName():s.name;if(s.name!=null&&s.name.getBytes(StandardCharsets.UTF_8).length>2048)return null;if(s.label.length()>120)s.label=s.label.substring(0,120);ByteArrayOutputStream out=new ByteArrayOutputStream();DataOutputStream data=new DataOutputStream(out);data.writeBoolean(s.visible);data.writeBoolean(s.name!=null);if(s.name!=null)data.writeUTF(s.name);data.writeUTF(s.label);s.originalTag=ORIG+Base64.getEncoder().encodeToString(out.toByteArray());if(!e.addScoreboardTag(s.originalTag))return null;return s;}
 public static void tick(JavaPlugin plugin,Collection<? extends Player> players){boolean enabled=plugin.getConfig().getBoolean("overhead-health",true);Set<UUID> seen=new HashSet<UUID>();for(Player p:players){if(!p.isOnline())continue;for(Entity raw:p.getNearbyEntities(24,24,24)){if(!(raw instanceof LivingEntity)||seen.size()>=256)continue;LivingEntity e=(LivingEntity)raw;if(e.isDead()||!e.isValid())continue;try{UUID id=e.getUniqueId();State s=states.get(id);if(s==null){s=read(e);if(s!=null&&s.lastName==null){tags(s);s=null;}}
   if(!enabled||!enemy(e)){if(s!=null)restore(s);states.remove(id);continue;}seen.add(id);if(s!=null&&s.e!=e){restore(s);s=null;}if(s!=null&&s.lastName!=null&&!s.lastName.equals(e.getCustomName())){tags(s);s=null;}if(s==null)s=fresh(e);if(s==null)continue;double max=e.getMaxHealth(),hp=e.getHealth();if(!Double.isFinite(max)||!Double.isFinite(hp)||max<=0){restore(s);continue;}int filled=(int)Math.ceil(10*Math.max(0,Math.min(1,hp/max)));StringBuilder bar=new StringBuilder(s.label+ChatColor.RESET+" "+(hp/max<=.25?ChatColor.RED:hp/max<=.6?ChatColor.YELLOW:ChatColor.GREEN));for(int i=0;i<10;i++){if(i==filled)bar.append(ChatColor.DARK_GRAY);bar.append('|');}bar.append(ChatColor.WHITE).append(' ').append(String.format(Locale.ROOT,"%.1f/%.1f",hp,max));String name=bar.toString();if(!name.equals(e.getCustomName()))e.setCustomName(name);String actual=e.getCustomName();s.lastName=actual;String next=LAST+hash(actual);if(!next.equals(s.lastTag)){if(s.lastTag!=null)e.removeScoreboardTag(s.lastTag);if(!e.addScoreboardTag(next)){restore(s);continue;}s.lastTag=next;}s.lastName=actual;e.setCustomNameVisible(true);states.put(id,s);
  }catch(Exception ignored){/* Preserve unknown/foreign name data rather than guess. */}}
 }for(Iterator<Map.Entry<UUID,State>> it=states.entrySet().iterator();it.hasNext();){Map.Entry<UUID,State> x=it.next();if(!seen.contains(x.getKey())){restore(x.getValue());it.remove();}}}
 public static void stop(){for(State s:new ArrayList<State>(states.values()))restore(s);states.clear();for(World w:Bukkit.getWorlds())for(LivingEntity e:w.getLivingEntities())try{State s=read(e);if(s!=null)restore(s);}catch(Exception ignored){}}
}
